"""Align an external voiceover (e.g. generated by the owner in ElevenLabs) to script_lines.py.

    python3 align.py voiceover.mp3 [VOICE] [LS]

Produces the same files as `synth.py VOICE LS` does, so the rest of the pipeline (scenes, captions, audio.py) works unchanged:
voice.wav (the external voice, 48 kHz), voice.json, timing.js. The script in script_lines.py must be what the voice actually says.

How: piper renders the same script as a reference (its word timings are exact), the external recording is split into lines at
its pauses (dynamic programming over the pauses, matching line lengths to the reference), and inside every line the reference is
time-warped onto the recording with DTW over MFCCs, which carries every word boundary over. Leading silence is trimmed to 0.12 s,
very long pauses between lines are shortened, 0.10 s of silence is kept at the end (the video loops).
Needs: the kit (synth.py, dl/piper, voices/VOICE) in the current folder, ffmpeg."""
import sys, os, json, shutil, subprocess, tempfile
import numpy as np
from scipy.io import wavfile
from scipy import signal
from scipy.fft import dct

SRC = sys.argv[1]; VOICE = sys.argv[2] if len(sys.argv) > 2 else 'ruslan'; LS = sys.argv[3] if len(sys.argv) > 3 else '0.76'
SR = 22050; OUT_SR = 48000; FR = 220; HOP = FR / SR            # analysis hop: 220 samples (~10 ms); times use the exact hop

def load(path, sr):
    raw = subprocess.run(['ffmpeg', '-v', 'error', '-i', path, '-ac', '1', '-ar', str(sr), '-f', 'f32le', '-'], capture_output=True, check=True).stdout
    return np.frombuffer(raw, np.float32).astype(np.float64)

# ---------- 1. reference: piper renders the same script, its word timings are exact ----------
ref_dir = tempfile.mkdtemp()
for f in ('synth.py', 'script_lines.py'): shutil.copy(f, ref_dir)
for d in ('dl', 'voices'): os.symlink(os.path.abspath(d), os.path.join(ref_dir, d))
subprocess.run([sys.executable, 'synth.py', VOICE, LS], cwd=ref_dir, check=True, capture_output=True)
R = json.load(open(os.path.join(ref_dir, 'voice.json')))
_, ra = wavfile.read(os.path.join(ref_dir, 'voice.wav')); ra = ra.astype(np.float64) / 32768
from importlib import util as _u
_spec = _u.spec_from_file_location('sl', 'script_lines.py'); _m = _u.module_from_spec(_spec); _spec.loader.exec_module(_m)
GAPS = [g for _, _, g in _m.LINES]
NL = len(R['lines'])

# ---------- 2. the recording: speech / pause map ----------
x = load(SRC, SR); x = x / (np.abs(x).max() + 1e-9)
xo = load(SRC, OUT_SR); xo = xo / (np.abs(xo).max() + 1e-9)
fr = FR; nfr = len(x) // fr
env = np.sqrt(np.convolve(x[:nfr * fr] ** 2, np.ones(fr * 3) / (fr * 3), 'same')[::fr][:nfr] + 1e-12)
edb = 20 * np.log10(env + 1e-9)
thr = max(np.percentile(edb, 95) - 32, np.percentile(edb, 10) + 8)
sil = edb < thr
pauses = []; i = 0                                                   # (start_s, end_s) of every pause >= 60 ms inside the speech
first = np.argmax(~sil); last = nfr - np.argmax(~sil[::-1])
while i < nfr:
    if sil[i]:
        j = i
        while j < nfr and sil[j]: j += 1
        if i > first and j < last and (j - i) * HOP >= 0.06: pauses.append((i * HOP, j * HOP))
        i = j
    else: i += 1
t_first, t_last = first * HOP, last * HOP

# ---------- 3. lines: choose NL-1 pauses as line boundaries (DP: line lengths match the reference, long pauses preferred) ----------
rdur = np.array([l['t1'] - l['t0'] for l in R['lines']])
P = len(pauses)
if P < NL - 1: sys.exit(f'only {P} pauses found for {NL} lines: the recording runs lines together, ask for clearer pauses between lines')
starts = [t_first] + [p[1] for p in pauses]; ends = [p[0] for p in pauses] + [t_last]
mu = np.log((t_last - t_first - sum(p[1] - p[0] for p in pauses) * 0.5) / rdur.sum())
def seg_cost(li, a, b):                                              # line li spans from starts[a] to ends[b]
    d = ends[b] - starts[a]
    if d <= 0.05: return 1e9
    return (np.log(d / rdur[li]) - mu) ** 2
INF = 1e18; f = np.full((NL, P + 1), INF); back = np.zeros((NL, P + 1), int)
for b in range(P + 1): f[0, b] = seg_cost(0, 0, b) - (0.6 * np.log(pauses[b][1] - pauses[b][0]) if b < P else 0)
for li in range(1, NL):
    for b in range(li, P + 1):
        best, arg = INF, -1
        for a in range(li, b + 1):                                   # line li starts after pause a-1
            v = f[li - 1, a - 1]
            if v >= INF: continue
            c = v + seg_cost(li, a, b) - (0.6 * np.log(pauses[b][1] - pauses[b][0]) if b < P else 0)
            if c < best: best, arg = c, a
        f[li, b] = best; back[li, b] = arg
if f[NL - 1, P] >= INF: sys.exit('could not split the recording into lines')
spans = []; b = P
for li in range(NL - 1, -1, -1):
    a = back[li, b] if li else 0
    spans.append((starts[a], ends[b])); b = a - 1
spans = spans[::-1]

# ---------- 4. words: DTW of MFCCs, reference line -> recorded line ----------
MEL = None
def mfcc(y):
    global MEL
    n_fft, hop = 512, fr
    if len(y) < n_fft: y = np.pad(y, (0, n_fft - len(y)))
    nf = 1 + (len(y) - n_fft) // hop
    idx = np.arange(n_fft)[None, :] + hop * np.arange(nf)[:, None]
    S = np.abs(np.fft.rfft(y[idx] * np.hanning(n_fft), axis=1)) ** 2
    if MEL is None:
        mel = lambda h: 2595 * np.log10(1 + h / 700); imel = lambda m: 700 * (10 ** (m / 2595) - 1)
        pts = imel(np.linspace(mel(80), mel(8000), 28)); bins = np.floor((n_fft + 1) * pts / SR).astype(int)
        MEL = np.zeros((26, n_fft // 2 + 1))
        for k in range(1, 27):
            l, c, r = bins[k - 1], bins[k], bins[k + 1]
            MEL[k - 1, l:c] = (np.arange(l, c) - l) / max(1, c - l); MEL[k - 1, c:r] = (r - np.arange(c, r)) / max(1, r - c)
    m = dct(np.log(S @ MEL.T + 1e-10), type=2, axis=1, norm='ortho')[:, 1:14]
    return (m - m.mean(0)) / (m.std(0) + 1e-6)
def dtw(A, B):
    C = np.sqrt(((A[:, None, :] - B[None, :, :]) ** 2).sum(-1)); n, m = C.shape
    D = np.full((n + 1, m + 1), np.inf); D[0, 0] = 0
    for i in range(1, n + 1):
        Ci = C[i - 1]; Dp = D[i - 1]; Di = D[i]
        diag = np.minimum(Dp[:-1], Dp[1:])                           # min(D[i-1,j-1], D[i-1,j])
        for j in range(1, m + 1):
            v = diag[j - 1] if diag[j - 1] < Di[j - 1] else Di[j - 1]
            Di[j] = Ci[j - 1] + v
    i, j, path = n, m, []
    while i > 0 and j > 0:
        path.append((i - 1, j - 1))
        k = np.argmin([D[i - 1, j - 1], D[i - 1, j], D[i, j - 1]])
        if k == 0: i, j = i - 1, j - 1
        elif k == 1: i -= 1
        else: j -= 1
    return path[::-1]
words_out = []; lines_out = []
for li, (L, (s0, s1)) in enumerate(zip(R['lines'], spans)):
    ry = ra[int(L['t0'] * SR):int(L['t1'] * SR)]; hy = x[int(s0 * SR):int(s1 * SR)]
    path = dtw(mfcc(hy), mfcc(ry)); hmap = {}
    for i, j in path: hmap.setdefault(j, []).append(i)
    jj = np.array(sorted(hmap)); ii = np.array([np.mean(hmap[j]) for j in jj])
    to_h = lambda tr: s0 + float(np.interp((tr - L['t0']) / HOP, jj, ii)) * HOP
    ws = [w for w in R['words'] if w['line'] == L['key']]
    for w in ws: words_out.append(dict(d=w['d'], t0=to_h(w['t0']), t1=to_h(w['t1']), line=L['key']))
    lines_out.append(dict(key=L['key'], t0=s0, t1=s1))
    words_out[-len(ws)]['t0'] = max(s0, min(words_out[-len(ws)]['t0'], s0 + 0.02)); words_out[-1]['t1'] = s1

# ---------- 5. the edit: trim the head, cap long pauses between lines, keep 0.10 s at the end ----------
LEAD = [0.0]
cuts = [(0.0, max(0.0, spans[0][0] - 0.12))]                        # (from, to) ranges of the recording to drop
for li in range(NL - 1):
    a, b = spans[li][1], spans[li + 1][0]; cap = GAPS[li] + 0.35
    if b - a > cap: m0 = a + cap / 2; cuts.append((m0, m0 + (b - a - cap)))
end_keep = spans[-1][1] + 0.10
def tmap(t):
    s = t + LEAD[0]
    for a, b in cuts:
        if t >= b: s -= (b - a)
        elif t > a: s -= (t - a)
    return s
if end_keep * OUT_SR > len(xo): xo = np.pad(xo, (0, int(end_keep * OUT_SR) - len(xo) + 1))   # the recording may stop right on the last word
keep = np.ones(len(xo), bool)
for a, b in cuts: keep[int(a * OUT_SR):int(b * OUT_SR)] = False
keep[int(end_keep * OUT_SR):] = False
y = xo[keep]
for a, b in cuts[1:]:                                                # 5 ms crossfade-free joins happen inside silence; tiny fades anyway
    p = int(round(tmap(b) * OUT_SR)); n = int(0.005 * OUT_SR)
    if n < p < len(y) - n: y[p - n:p + n] *= np.concatenate([np.linspace(1, 0.3, n), np.linspace(0.3, 1, n)])
lead = max(0.0, 0.12 - (spans[0][0] - cuts[0][1]))                    # always 0.12 s of silence before the first word, like synth.py
if lead > 0: y = np.concatenate([np.zeros(int(round(lead * OUT_SR))), y])
LEAD[0] = lead
total = round(len(y) / OUT_SR, 3)
wavfile.write('voice.wav', OUT_SR, (y / (np.abs(y).max() + 1e-9) * 0.95 * 32767).astype(np.int16))
W = [dict(d=w['d'], t0=round(tmap(w['t0']), 3), t1=round(tmap(w['t1']), 3), line=w['line']) for w in words_out]
for k in range(1, len(W)):                                            # keep words ordered and at least 40 ms long
    W[k]['t0'] = max(W[k]['t0'], W[k - 1]['t0'] + 0.04)
    W[k - 1]['t1'] = max(W[k - 1]['t1'], W[k - 1]['t0'] + 0.04)
LN = [dict(key=l['key'], t0=round(tmap(l['t0']), 3), t1=round(tmap(l['t1']), 3)) for l in lines_out]
T = dict(total=total, words=W, lines=LN)
json.dump(T, open('voice.json', 'w'), ensure_ascii=False, indent=1)
open('timing.js', 'w').write('window.TIMING=' + json.dumps(T, ensure_ascii=False) + ';')
print(f'aligned {SRC}: total {total}s, {len(W)} words ({len(W) / total:.2f}/s), {P} pauses found, {len(cuts) - 1} long pauses shortened')
for l, (s0, s1), r in zip(LN, spans, rdur): print(f"  {l['key']:8s} {l['t0']:7.3f} {l['t1']:7.3f}  ({s1 - s0:.2f}s, reference {r:.2f}s)")
shutil.rmtree(ref_dir, ignore_errors=True)
